WITH flattened AS (SELECT id, customer_id, created_at, coupon_codes, item.product_id, item.qty, item.price FROM carts LATERAL VIEW EXPLODE(items) li AS item) SELECT id, customer_id, created_at, coupon_codes, product_id, qty, price, ROUND(price / SUM(price) OVER (PARTITION BY customer_id), 4) AS price_share, RANK() OVER (PARTITION BY customer_id ORDER BY price DESC) AS price_rank, PERCENT_RANK() OVER (PARTITION BY customer_id ORDER BY price DESC NULLS LAST) AS price_percent_rank FROM flattened;
